// main.py's fireworks_ai embedding arm: the passed key, litellm.api_key and FIREWORKS_AI_API_KEY, the base as it came, and a call with no headers
fn fireworks_ai(call: &EmbeddingCall, settings: DispatchSettings<'_>) -> EmbeddingCall {
    let mut resolved = call.clone();
    resolved.api_key = first_secret([
        call.api_key.as_ref(),
        settings.api_key,
        settings.env_fireworks_ai_api_key,
    ]);
    resolved.headers = None;
    resolved
}
